<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Escritório Virtual · Sala de Operações</title>
<style>
:root{font-family:Inter,ui-sans-serif,system-ui,sans-serif;color:#f7f1ea;background:#120f0d;--orange:#ff6428;--cream:#f6efe7;--muted:#b7aaa0;--panel:#201916;--line:#4a342b;--green:#43d58a;--yellow:#ffc857}
*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at 50% 8%,#3a2117,#120f0d 56%)}button{font:inherit;color:inherit}.shell{max-width:1500px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}.kicker{font-size:12px;letter-spacing:.18em;color:var(--orange);text-transform:uppercase}.title{font-size:clamp(28px,4vw,52px);line-height:.98;margin:8px 0}.subtitle{color:var(--muted);max-width:670px}.controls{display:flex;gap:8px;flex-wrap:wrap}.controls button,.filter{background:#211814;border:1px solid var(--line);border-radius:8px;padding:10px 13px}.controls button.active{background:var(--orange);color:#1a0c07;border-color:var(--orange);font-weight:800}.dashboard{display:grid;grid-template-columns:minmax(0,1.45fr) 360px;gap:16px;margin-top:22px}.floor{position:relative;min-height:690px;overflow:hidden;border:1px solid #6e4431;border-radius:18px;background:linear-gradient(140deg,#2a1c17,#120f0d 65%);box-shadow:0 20px 70px #0008}.floor:before{content:"";position:absolute;inset:12% 8% 9%;background:repeating-linear-gradient(0deg,transparent 0 70px,#4b342d 71px 73px),repeating-linear-gradient(90deg,transparent 0 110px,#4b342d 111px 113px);transform:skewY(-10deg) rotate(-2deg);opacity:.45}.floor-head{position:relative;z-index:2;padding:22px;display:flex;justify-content:space-between;align-items:center}.demo{display:inline-block;margin:8px 0 0;padding:6px 9px;border:1px solid #91603e;border-radius:6px;color:#ffd6ad;font-size:10px;letter-spacing:.05em;text-transform:uppercase}.live{display:inline-flex;align-items:center;gap:7px;color:var(--green);font-size:12px}.dot{width:8px;height:8px;border-radius:50%;background:var(--green);box-shadow:0 0 14px var(--green)}.rooms{position:absolute;inset:105px 30px 32px;z-index:1}.room{position:absolute;border:2px solid #3d2a22;background:#191310d9;box-shadow:0 12px 24px #0007;transform:skewY(-10deg) rotate(-1deg);padding:14px;border-radius:8px}.room h3{margin:0 0 4px;font-size:13px;color:var(--orange);text-transform:uppercase;letter-spacing:.08em}.room small{color:var(--muted)}.room[data-room=estrategia]{left:3%;top:8%;width:43%;height:29%}.room[data-room=inteligencia]{right:3%;top:5%;width:42%;height:34%}.room[data-room=criacao]{left:8%;top:45%;width:43%;height:31%}.room[data-room=publicacao]{right:7%;top:50%;width:40%;height:27%}.desks{display:flex;flex-wrap:wrap;gap:11px;margin-top:14px}.agent{min-width:128px;flex:1;border:1px solid #634538;background:#2b1c16;padding:9px;border-radius:7px;cursor:pointer;transition:.18s}.person{display:block;position:relative;width:52px;height:37px;margin:0 auto 7px}.person:before{content:"";position:absolute;left:20px;top:0;width:12px;height:12px;border-radius:50%;background:#d89b72;box-shadow:inset -2px -1px #ad6d50}.person:after{content:"";position:absolute;left:15px;top:11px;width:23px;height:17px;border-radius:10px 10px 4px 4px;background:var(--shirt,#ff6428);box-shadow:0 13px 0 -8px #2b1c16}.person i{position:absolute;left:4px;bottom:1px;width:45px;height:5px;border-radius:3px;background:#bd7442;box-shadow:0 6px 0 -1px #6a3d28}.person.pink{--shirt:#e76f9f}.person.blue{--shirt:#5e9be6}.person.purple{--shirt:#9b78d1}.person.green{--shirt:#55b887}.person.orange{--shirt:#f19a4b}.agent:hover,.agent.selected{border-color:var(--orange);transform:translateY(-3px);box-shadow:0 0 0 2px #ff642855}.agent b{display:block;font-size:12px}.agent span{font-size:10px;color:var(--muted)}.agent i{display:block;margin-top:7px;font-size:10px;font-style:normal}.status{display:inline-flex;gap:5px;align-items:center;margin-top:6px;color:var(--yellow)}.status.ok{color:var(--green)}.status.wait{color:var(--yellow)}.status.bad{color:#ff8e72}.process{position:absolute;left:24px;right:24px;bottom:19px;z-index:3;padding:15px 18px;border:1px solid #754936;background:#17100ddf;backdrop-filter:blur(8px);border-radius:14px}.steps{display:grid;grid-template-columns:repeat(9,1fr);gap:4px}.step{position:relative;text-align:center;color:#8e7f76;font-size:10px}.step:before{content:attr(data-n);display:grid;place-items:center;margin:auto auto 6px;width:30px;height:30px;border:1px solid #6e5146;border-radius:50%;font-size:12px}.step.done,.step.active{color:var(--cream)}.step.done:before{background:var(--green);color:#0c2116;border-color:var(--green)}.step.active:before{background:var(--orange);color:#1b0e08;border-color:var(--orange)}.side{display:flex;flex-direction:column;gap:14px}.panel{border:1px solid var(--line);background:#1d1613e8;border-radius:14px;padding:17px}.panel h2{font-size:15px;margin:0 0 14px}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:8px}.metric{background:#281b16;border-radius:9px;padding:12px}.metric strong{font-size:24px;color:var(--orange);display:block}.metric span{font-size:11px;color:var(--muted)}.queue{display:grid;gap:8px}.queue-item{border-left:3px solid var(--orange);padding:8px 10px;background:#271b16;font-size:12px}.queue-item small{display:block;color:var(--muted);margin-top:4px}.gate{border-color:#8b512d;background:linear-gradient(135deg,#2a1a13,#17100d)}.gate strong{display:block;color:var(--orange);font-size:20px}.gate button{margin-top:12px;width:100%;padding:11px;border:0;border-radius:8px;background:var(--orange);color:#1c0c06;font-weight:800;cursor:pointer}.gate button:disabled{opacity:.45;cursor:not-allowed}.log{max-height:190px;overflow:auto;color:var(--muted);font-size:11px;line-height:1.5}.log div{padding:6px 0;border-bottom:1px solid #3b2923}.legend{display:flex;gap:10px;flex-wrap:wrap;font-size:11px;color:var(--muted)}.legend b{color:var(--cream)}
@media(max-width:1050px){.dashboard{grid-template-columns:1fr}.side{display:grid;grid-template-columns:repeat(2,1fr)}.gate{grid-column:span 2}}@media(max-width:680px){.shell{padding:14px}.side{display:flex}.floor{min-height:760px}.rooms{inset:90px 14px 30px}.room{position:relative!important;left:auto!important;right:auto!important;top:auto!important;width:100%!important;height:auto!important;margin-bottom:10px;transform:none}.rooms{overflow:auto}.steps{grid-template-columns:repeat(4,1fr);gap:8px}.process{left:12px;right:12px}.top{display:block}.controls{margin-top:15px}}
</style>
</head>
<body><main class="shell">
<header class="top"><div><div class="kicker">Vitrine Social Mídia · Escritório Virtual</div><h1 class="title">Sala de operações</h1><p class="subtitle">Agentes trabalhando em camadas. Cada entrega passa pela VIA antes de chegar ao próximo agente ou à publicação.</p><span class="demo">Protótipo interativo · dados demonstrativos · sem execução de agentes</span></div><div class="controls"><button class="active" data-view="floor">Piso operacional</button><button data-view="queue">Fila de missões</button><button data-view="audit">Auditoria VIA</button></div></header>
<section class="dashboard"><div class="floor"><div class="floor-head"><div><b>Agência de Conteúdo IA</b><div class="live">● ciclo demonstrativo · campanha Vitrine Social</div></div><select class="filter" aria-label="Selecionar produto"><option>Vitrine Social Mídia</option><option>Marketing IA</option></select></div><div class="rooms">
<section class="room" data-room="estrategia"><h3>01 · Estratégia</h3><small>Briefing e direção</small><div class="desks"><button class="agent selected" data-agent="planner"><span class="person pink" aria-hidden="true"><i></i></span><b>Planner IA</b><span>pauta e briefing</span><i class="status ok">● produzindo</i></button><button class="agent" data-agent="pesquisa"><span class="person blue" aria-hidden="true"><i></i></span><b>Radar de tendências</b><span>dados e referências</span><i class="status wait">● aguardando</i></button></div></section>
<section class="room" data-room="inteligencia"><h3>02 · Inteligência</h3><small>Pesquisa, análise e julgamento</small><div class="desks"><button class="agent" data-agent="copy"><span class="person orange" aria-hidden="true"><i></i></span><b>Copy IA</b><span>gancho, legenda e CTA</span><i class="status wait">● bloqueado pela VIA</i></button><button class="agent" data-agent="qa"><span class="person purple" aria-hidden="true"><i></i></span><b>QA de marca</b><span>formato e riscos</span><i class="status wait">● aguardando</i></button></div></section>
<section class="room" data-room="criacao"><h3>03 · Criação</h3><small>Peças e roteiros</small><div class="desks"><button class="agent" data-agent="creative"><span class="person pink" aria-hidden="true"><i></i></span><b>Direção Criativa</b><span>visual e roteiro</span><i class="status wait">● aguardando</i></button><button class="agent" data-agent="video"><span class="person blue" aria-hidden="true"><i></i></span><b>Produtor de vídeo</b><span>cenas e edição</span><i class="status wait">● aguardando</i></button></div></section>
<section class="room" data-room="publicacao"><h3>04 · Distribuição</h3><small>Agendamento condicionado</small><div class="desks"><button class="agent" data-agent="social"><span class="person green" aria-hidden="true"><i></i></span><b>Social Media IA</b><span>Meta e calendário</span><i class="status bad">● sem autorização</i></button></div></section></div>
<div class="process"><div class="steps"><div class="step done" data-n="1">DADOS</div><div class="step done" data-n="2">ANÁLISE</div><div class="step active" data-n="3">JUIZ</div><div class="step" data-n="4">REUNIÃO</div><div class="step" data-n="5">ROTEIRO</div><div class="step" data-n="6">MEMÓRIA</div><div class="step" data-n="7">PRODUÇÃO</div><div class="step" data-n="8">PUBLICAÇÃO</div><div class="step" data-n="✓">APROVA</div></div></div></div>
<aside class="side"><section class="panel metrics"><div class="metric"><strong>8</strong><span>camadas</span></div><div class="metric"><strong>7</strong><span>postos da agência</span></div><div class="metric"><strong>1</strong><span>gate pendente</span></div><div class="metric"><strong>0</strong><span>publicações livres</span></div></section><section class="panel gate"><strong>Gate VIA</strong><p class="subtitle">O Copy IA entregou a primeira versão. A VIA precisa aprovar ou devolver ao mesmo agente.</p><div class="legend"><span>Agente atual: <b>Planner IA</b></span><span>Versão: <b>v1</b></span></div><button id="approve">Simular aprovação VIA</button></section><section class="panel"><h2>Fila de atividade</h2><div class="queue"><div class="queue-item">Planner IA iniciou a pauta<small>há 2 min · versão v1</small></div><div class="queue-item">VIA solicitou evidência de público<small>há 1 min · revisão pendente</small></div><div class="queue-item">Social Media IA bloqueado<small>aguarda aprovação do gestor</small></div></div></section><section class="panel"><h2>Log auditável</h2><div class="log" id="log"><div>14:32 · ciclo criado para Vitrine Social Mídia</div><div>14:33 · Planner IA assumiu a tarefa</div><div>14:34 · VIA abriu gate de handoff</div></div></section></aside></section></main>
<script>
async function hydrateOperationalState(){
  try{
    const source=(window.location.hostname==='127.0.0.1'||window.location.hostname==='localhost')?'state.demo.json':'/cockpit/escritorio-agentes/estado'; const snapshot=await fetch(source,{cache:'no-store',credentials:'same-origin'}).then(r=>r.ok?r.json():Promise.reject(new Error('state_unavailable')));
    const agents=new Map(snapshot.agents.map(agent=>[agent.id,agent]));
    document.querySelectorAll('[data-agent]').forEach(card=>{
      const agent=agents.get(card.dataset.agent); if(!agent) return;
      const status=card.querySelector('.status');
      if(status){
        const labels={working:'● produzindo',awaiting_via_review:'● aguardando VIA',blocked:'● bloqueado',idle:'● aguardando',ready_for_handoff:'● liberado pela VIA',failed:'● falhou'};
        status.textContent=labels[agent.status]||('● '+agent.status);
        status.className='status '+(agent.status==='working'||agent.status==='ready_for_handoff'?'ok':agent.status==='failed'?'bad':'wait');
      }
      card.title='Agente '+agent.name+' · estado persistido: '+agent.status;
    });
    const gate=snapshot.gate||{};
    const gateText=document.querySelector('.gate p');
    if(gateText) gateText.textContent=gate.status==='awaiting_review'?'A versão '+gate.version+' aguarda decisão da VIA. O próximo agente permanece bloqueado.':'Estado VIA: '+gate.status;
    const gateMeta=document.querySelector('.gate .legend');
    if(gateMeta) gateMeta.innerHTML='<span>Tarefa: <b>'+(gate.task_id||'—')+'</b></span><span>Agente: <b>'+(gate.agent_id||'—')+'</b></span><span>Versão: <b>'+(gate.version||'—')+'</b></span>';
    const activity=document.querySelector('.queue');
    if(activity&&Array.isArray(snapshot.activity)) activity.innerHTML=snapshot.activity.slice().reverse().map(event=>'<div class="queue-item">'+event.message+'<small>'+event.event_type+' · '+event.occurred_at+'</small></div>').join('');
    const log=document.querySelector('#log');
    if(log&&Array.isArray(snapshot.activity)) log.innerHTML=snapshot.activity.map(event=>'<div>'+event.occurred_at+' · '+event.message+'</div>').join('');
  }catch(error){
    document.querySelector('.demo').textContent='Protótipo · snapshot indisponível';
  }
}
hydrateOperationalState();
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-view]').forEach(item=>item.classList.remove('active'));button.classList.add('active');const title=button.dataset.view==='floor'?'Piso operacional':button.dataset.view==='queue'?'Fila de missões':'Auditoria VIA';document.querySelector('.floor-head b').textContent=title+' · Agência de Conteúdo IA';}));const log=document.querySelector('#log'),approve=document.querySelector('#approve');document.querySelectorAll('.agent').forEach(a=>a.addEventListener('click',()=>{document.querySelectorAll('.agent').forEach(x=>x.classList.remove('selected'));a.classList.add('selected');log.insertAdjacentHTML('afterbegin','<div>agora · selecionado '+a.dataset.agent+'</div>')}));approve.addEventListener('click',()=>{approve.disabled=true;approve.textContent='Handoff aprovado · Copy IA liberado';log.insertAdjacentHTML('afterbegin','<div>agora · DEMO: VIA aprovou Planner → Copy IA (não persistido)</div>');document.querySelector('[data-agent=copy] .status').textContent='● liberado pela VIA';document.querySelector('[data-agent=copy] .status').className='status ok';document.querySelector('.step.active').className='step done';document.querySelectorAll('.step')[3].className='step active'});</script>
</body></html>





